# -*- coding: utf-8 -*-
"""Professional Services: 120 industries. One concrete marketing fact each."""

P = {}

# --- Legal services (16) ---
P["Personal injury law firms"] = "Among the most expensive keywords in advertising, where the first firm to make contact signs a disproportionate share of matters."
P["Medical malpractice law firms"] = "Long, expensive matters with heavy screening, so the marketing job is filtering rather than generating volume."
P["Employment law firms"] = "Employee and employer work require separate positioning, and running both from one site creates a conflict problem in the buyer's mind."
P["Family law firms"] = "People search at their worst moment and choose on approachability, so fee transparency and process clarity outperform credential lists."
P["Criminal defence law firms"] = "Urgent, often searched at night or from a police station, which makes twenty four hour answering the deciding factor."
P["Immigration law firms"] = "Policy changes create sudden search spikes, and firms that publish accurate updates capture them."
P["Corporate law firms"] = "Relationship and referral driven, where individual partner reputation carries far more weight than the firm's site."
P["Commercial litigation firms"] = "In-house counsel research the individual litigator, so partner profiles with real matter experience are the money pages."
P["Real estate law firms"] = "Volume driven with fee competition, where turnaround time and closing reliability are what agents refer on."
P["Estate planning law firms"] = "Life events trigger the search, and content explaining what happens without a will converts better than service descriptions."
P["Tax law firms"] = "Triggered by an audit or a notice, which makes the search urgent, specific and high intent."
P["Class action law firms"] = "Campaign-specific and time-bound, where speed to build a claimant landing page decides participation."
P["Disability law firms"] = "Claimants have usually been denied once already, so content about the appeal process is what they are searching."
P["Insurance defence firms"] = "Insurers are the client, which makes this a business to business panel relationship rather than a consumer practice."
P["Intellectual property law firms"] = "Technical specialisation by field is what clients filter on, and generalist IP positioning loses to it."
P["Multi-office law firms"] = "Offices with near-identical pages compete against each other, and most multi-office firms have exactly that."

# --- Financial services (17) ---
P["Financial advisory firms"] = "Fee structure is what prospective clients most want to know and what almost no firm publishes."
P["Wealth management firms"] = "Minimum investment thresholds should be stated, because unqualified enquiries consume advisor time that cannot be recovered."
P["Investment management firms"] = "Performance claims are restricted by securities regulators, and marketing needs compliance sign-off before publishing."
P["Private wealth firms"] = "Referral and relationship driven, where the website's job is confirming credibility rather than generating leads."
P["Mortgage brokerages"] = "Rate driven search where speed of response decides the application, and rates change often enough to make static pages a liability."
P["Mortgage lenders"] = "Rate comparison sites dominate the search results, which pushes lenders toward broker relationships and brand."
P["Credit unions"] = "Membership eligibility is the first filter and it is frequently unclear on the site."
P["Community banks"] = "Local presence is the differentiator against national institutions, and branch-level content is how it gets expressed."
P["Commercial lenders"] = "Business borrowers compare terms and speed to funding, which are the two things worth publishing."
P["Fintech companies"] = "Regulatory positioning determines what can be claimed and it changes by jurisdiction."
P["Payments companies"] = "Pricing transparency is a differentiator in a category built on obscured fee structures."
P["Foreign exchange companies"] = "Rate and fee comparison drives the decision, and hidden margin in the spread is the industry norm buyers have learned to check."
P["Consumer finance companies"] = "Lending advertising is regulated with mandatory disclosure requirements on rates and terms."
P["Equipment finance companies"] = "Sold through vendor and dealer relationships, which makes the partner channel the growth priority."
P["Private equity firms"] = "Marketing serves deal flow and limited partner relations, which are entirely different audiences."
P["Venture capital firms"] = "Founders choose investors on reputation and portfolio, so the partner content is the marketing."
P["Family offices"] = "Discretion is the norm, and most do not market at all, which makes visibility itself a positioning decision."

# --- Insurance (11) ---
P["Insurance brokerages"] = "Personal lines is a price comparison fight while commercial is relationship driven, and one site usually serves neither well."
P["Commercial insurance brokerages"] = "Industry specialisation is what buyers filter on, and a page per industry outperforms a general commercial page."
P["Personal insurance brokerages"] = "Aggregators dominate the search results, so brokers compete on advice and claims support rather than quote speed."
P["Employee benefits firms"] = "HR leaders buy on plan design and administrative burden, and the monthly cost comes third."
P["Life insurance agencies"] = "Life events trigger the search, and needs-based content converts better than product comparison."
P["Health insurance agencies"] = "Enrolment periods concentrate demand into a few weeks, which makes campaign timing the main lever."
P["Property and casualty agencies"] = "Renewal timing drives switching, and campaigns aligned to renewal months outperform continuous spend."
P["Specialty insurance firms"] = "Narrow niches with low search volume where a well-built page can own the category outright."
P["Managing general agencies"] = "Brokers are the customer, which makes this business to business distribution rather than consumer insurance."
P["Insurtech companies"] = "Regulatory licensing by jurisdiction determines where the product can be advertised at all."
P["Multi-office insurance firms"] = "Local presence and licensing vary by office, and the site has to reflect both accurately."

# --- Accounting and tax (11) ---
P["Accounting firms"] = "Compliance work is commoditising and advisory is where growth is, but most firms market the compliance."
P["CPA firms"] = "Designation rules limit how specialisation can be described, and the permitted language varies by professional body."
P["Bookkeeping firms"] = "Software has compressed pricing, so the position has to be advisory support rather than data entry."
P["Tax advisory firms"] = "Seasonal search spikes around filing deadlines with a long quiet period that advisory content should fill."
P["Corporate tax firms"] = "Sold to finance leaders on risk reduction and planning, which are different messages from consumer tax."
P["Forensic accounting firms"] = "Lawyers and insurers are the referral source, so the marketing audience is professional rather than commercial."
P["Fractional CFO firms"] = "A growing category that many buyers do not know exists, so content has to explain the model first."
P["Payroll service firms"] = "Compliance accuracy and support responsiveness are the buying criteria, and price is a distant third."
P["Audit firms"] = "Independence rules restrict what can be marketed and to whom, and getting it wrong is a regulatory issue."
P["Valuation firms"] = "Triggered by a transaction, dispute or estate, which makes the search event driven and specific."
P["Insolvency and restructuring firms"] = "People search in distress and often anonymously, which makes discreet enquiry options important."

